# --- 파일 자동 저장 설정 ---
HISTORY_FILE = "dishwashing_history.csv"

def load_history():
    if os.path.exists(HISTORY_FILE):
        try:
            return pd.read_csv(HISTORY_FILE, encoding="utf-8-sig")
        except Exception:
            return pd.DataFrame(columns=["일시 (Timestamp)", "당첨자 (Winners)", "참가자 (Participants)", "언어 (Language)"])
    return pd.DataFrame(columns=["일시 (Timestamp)", "당첨자 (Winners)", "참가자 (Participants)", "언어 (Language)"])

def save_result(winners_list, participants_list, lang_name):
    timestamp_str = datetime.now().strftime("%Y-%m-%d %H:%M:%S")
    winners_str = ", ".join(winners_list)
    participants_str = ", ".join(participants_list)
    new_row = pd.DataFrame([{
        "일시 (Timestamp)": timestamp_str,
        "당첨자 (Winners)": winners_str,
        "참가자 (Participants)": participants_str,
        "언어 (Language)": lang_name
    }])
    
    if os.path.exists(HISTORY_FILE):
        new_row.to_csv(HISTORY_FILE, mode="a", header=False, index=False, encoding="utf-8-sig")
    else:
        new_row.to_csv(HISTORY_FILE, mode="w", header=True, index=False, encoding="utf-8-sig")

